do $$ declare t text;begin foreach t in array array['water_settings','water_logs'] loop
 execute format('alter table public.%I enable row level security',t);
 execute format('drop policy if exists phase2_read on public.%I',t);
 execute format('create policy phase2_read on public.%I for select to authenticated using(public.can_view(user_id))',t);
 execute format('drop policy if exists phase2_write on public.%I',t);
 execute format('create policy phase2_write on public.%I for all to authenticated using(public.can_full(user_id)) with check(public.can_full(user_id))',t);
 execute format('drop trigger if exists phase2_log on public.%I',t);
