create or replace function public.check_water_intake() returns void language plpgsql security definer set search_path=public as $$
declare s water_settings;total int;d text := to_char(now() at time zone 'Asia/Kolkata','YYYY-MM-DD');
begin
 if extract(hour from now() at time zone 'Asia/Kolkata')<16 then return;end if;
 for s in select * from water_settings where public.can_view(user_id) loop
 select coalesce(sum(amount_ml),0) into total from water_logs where user_id=s.user_id and (created_at at time zone 'Asia/Kolkata')::date=d::date;
 if total<s.daily_goal_ml*.4 then insert into alerts(user_id,type,message,data) values(s.user_id,'low_water','💧',jsonb_build_object('day',d,'amount',total)) on conflict do nothing;end if;
 end loop;
end $$;
