create table if not exists public.safe_zones(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles on delete cascade,name text not null,lat double precision not null check(lat between -90 and 90),lng double precision not null check(lng between -180 and 180),radius_m int not null default 300 check(radius_m between 100 and 2000),active boolean not null default true,created_by uuid default auth.uid(),created_at timestamptz not null default now());
create table if not exists public.location_pings(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles on delete cascade,lat double precision not null check(lat between -90 and 90),lng double precision not null check(lng between -180 and 180),accuracy double precision,created_at timestamptz not null default now());
create index if not exists location_recent on public.location_pings(user_id,created_at desc);
create or replace function public.can_see_location(target uuid) returns boolean language sql stable security definer set search_path=public as $$select target=auth.uid() or exists(select 1 from location_sharing s where s.user_id=target and s.enabled and (public.family_level(target)='full' or (s.share_with_family and public.family_level(target)='view')))$$;
alter table public.location_sharing enable row level security;
drop policy if exists location_consent_read on public.location_sharing;
create policy location_consent_read on public.location_sharing for select to authenticated using(public.can_view(user_id));
drop policy if exists location_consent_write on public.location_sharing;
create policy location_consent_write on public.location_sharing for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
alter table public.safe_zones enable row level security;
drop policy if exists zones_read on public.safe_zones;
create policy zones_read on public.safe_zones for select to authenticated using(public.can_see_location(user_id));
drop policy if exists zones_write on public.safe_zones;
create policy zones_write on public.safe_zones for all to authenticated using(public.can_full(user_id) and public.can_see_location(user_id)) with check(public.can_full(user_id) and public.can_see_location(user_id));
alter table public.location_pings enable row level security;
drop policy if exists pings_read on public.location_pings;
create policy pings_read on public.location_pings for select to authenticated using(public.can_see_location(user_id) and created_at>now()-interval '7 days');
create or replace function public.distance_m(a double precision,b double precision,c double precision,d double precision) returns double precision language sql immutable as $$select 6371000*2*asin(least(1,sqrt(power(sin(radians(c-a)/2),2)+cos(radians(a))*cos(radians(c))*power(sin(radians(d-b)/2),2))))$$;
create or replace function public.record_location(latitude double precision,longitude double precision,accuracy_m double precision) returns void language plpgsql security definer set search_path=public as $$
declare s location_sharing;out_now boolean;
begin
 if not public.is_member() then raise exception 'Member access required';end if;
 select * into s from location_sharing where user_id=auth.uid() and enabled for update;if not found then raise exception 'Location consent required';end if;
 if exists(select 1 from location_pings p where p.user_id=auth.uid() and p.created_at>now()-interval '60 seconds' and distance_m(p.lat,p.lng,latitude,longitude)<50) then return;end if;
 insert into location_pings(user_id,lat,lng,accuracy) values(auth.uid(),latitude,longitude,accuracy_m);
 if exists(select 1 from safe_zones where user_id=auth.uid() and active) then
 select not exists(select 1 from safe_zones where user_id=auth.uid() and active and distance_m(lat,lng,latitude,longitude)<=radius_m) into out_now;
 if out_now is distinct from s.outside then
 insert into alerts(user_id,type,message,data) values(auth.uid(),case when out_now then 'zone_exit' else 'zone_return' end,'📍',jsonb_build_object('lat',latitude,'lng',longitude));
 update location_sharing set outside=out_now,updated_at=now() where user_id=auth.uid();
 end if;end if;
end $$;
-- Run daily using Supabase Cron; never exposed to browser clients.
create or replace function public.cleanup_location_pings() returns void language sql security definer set search_path=public as $$delete from location_pings where created_at<now()-interval '7 days'$$;
revoke all on function public.cleanup_location_pings() from public,anon,authenticated;
revoke all on function public.record_location(double precision,double precision,double precision) from public;
grant execute on function public.record_location(double precision,double precision,double precision) to authenticated;
do $$declare t text;begin foreach t in array array['safe_zones','location_sharing'] loop
 execute format('drop trigger if exists phase2_log on public.%I',t);
 execute format('create trigger phase2_log after insert or update or delete on public.%I for each row execute function public.log_family_change()',t);
end loop;end $$;
-- Location coordinates must never leak through the general family alerts policy.
drop policy if exists alerts_read on public.alerts;
create policy alerts_read on public.alerts for select to authenticated using(public.can_view(user_id) and (type not in ('zone_exit','zone_return') or public.can_see_location(user_id)));
