create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$
declare r text:=coalesce(new.raw_user_meta_data->>'role','user');begin
 if r not in ('user','family','volunteer') then r:='user';end if;
 insert into profiles(id,name,phone,role,is_volunteer) values(new.id,coalesce(new.raw_user_meta_data->>'name',split_part(new.email,'@',1)),new.raw_user_meta_data->>'phone',r,r='volunteer') on conflict do nothing;
 insert into user_settings(user_id) values(new.id) on conflict do nothing;
 insert into checkin_rules(user_id) values(new.id) on conflict do nothing;return new;end $$;
create table if not exists public.volunteer_profiles(user_id uuid primary key references public.profiles on delete cascade,skills text[] not null default '{}',area_name text,lat double precision check(lat between -90 and 90),lng double precision check(lng between -180 and 180),radius_km int not null default 5 check(radius_km between 1 and 100),available boolean not null default true,institution text,verified boolean not null default false,total_hours numeric not null default 0,created_at timestamptz not null default now());
create table if not exists public.help_requests(id uuid primary key default gen_random_uuid(),requester_id uuid default auth.uid() references public.profiles,requested_for_user_id uuid references public.profiles,category text not null,title text not null,description text,voice_url text,preferred_time timestamptz,lat double precision not null check(lat between -90 and 90),lng double precision not null check(lng between -180 and 180),public_lat double precision,public_lng double precision,place_name text,urgency text not null default 'normal' check(urgency in ('normal','soon')),status text not null default 'open' check(status in ('open','accepted','in_progress','completed','cancelled')),volunteer_id uuid references public.profiles,accepted_at timestamptz,completed_at timestamptz,hours_spent numeric,notify_family boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.help_feedback(id uuid primary key default gen_random_uuid(),request_id uuid not null unique references public.help_requests on delete cascade,user_id uuid not null default auth.uid() references public.profiles,rating int not null check(rating between 1 and 5),thanks_message text,voice_url text,created_at timestamptz not null default now());
create or replace function public.guard_volunteer() returns trigger language plpgsql security definer set search_path=public as $$begin
 if auth.uid() is null or public.is_admin() then return new;end if;
 if tg_op='INSERT' then new.verified:=false;new.total_hours:=0;
 elsif new.verified is distinct from old.verified or new.total_hours is distinct from old.total_hours then raise exception 'Protected volunteer fields';end if;return new;end $$;
drop trigger if exists volunteer_guard on public.volunteer_profiles;
create trigger volunteer_guard before insert or update on public.volunteer_profiles for each row execute function public.guard_volunteer();
create or replace function public.prepare_help() returns trigger language plpgsql security definer set search_path=public as $$begin
 if new.requester_id is distinct from auth.uid() and auth.uid() is not null then raise exception 'Requester mismatch';end if;
 if new.requested_for_user_id is not null and not coalesce(can_full(new.requested_for_user_id),false) and auth.uid() is not null then raise exception 'Family permission required';end if;
 new.status:='open';new.volunteer_id:=null;new.accepted_at:=null;new.completed_at:=null;new.hours_spent:=null;
 new.public_lat:=new.lat+(200+random()*300)/111320 * case when random()<.5 then -1 else 1 end;
 new.public_lng:=new.lng;return new;end $$;
drop trigger if exists help_prepare on public.help_requests;
create trigger help_prepare before insert on public.help_requests for each row execute function public.prepare_help();
alter table public.volunteer_profiles enable row level security;
drop policy if exists volunteer_read on public.volunteer_profiles;
create policy volunteer_read on public.volunteer_profiles for select to authenticated using(user_id=auth.uid() or public.is_admin());
drop policy if exists volunteer_write on public.volunteer_profiles;
create policy volunteer_write on public.volunteer_profiles for all to authenticated using(user_id=auth.uid() or public.is_admin()) with check(user_id=auth.uid() or public.is_admin());
alter table public.help_requests enable row level security;
drop policy if exists help_read on public.help_requests;
create policy help_read on public.help_requests for select to authenticated using(requester_id=auth.uid() or volunteer_id=auth.uid() or public.can_view(requested_for_user_id) or public.is_admin());
drop policy if exists help_create on public.help_requests;
create policy help_create on public.help_requests for insert to authenticated with check(requester_id=auth.uid() and (requested_for_user_id is null or public.can_full(requested_for_user_id)));
-- No direct UPDATE policy: atomic lifecycle RPCs own transitions.
alter table public.help_feedback enable row level security;
drop policy if exists feedback_read on public.help_feedback;
create policy feedback_read on public.help_feedback for select to authenticated using(exists(select 1 from help_requests r where r.id=request_id and (r.requester_id=auth.uid() or r.volunteer_id=auth.uid())) or public.is_admin());
drop policy if exists feedback_create on public.help_feedback;
create policy feedback_create on public.help_feedback for insert to authenticated with check(user_id=auth.uid() and exists(select 1 from help_requests r where r.id=request_id and r.status='completed' and r.requester_id=auth.uid()));
create or replace view public.help_requests_public as select id,category,title,description,preferred_time,public_lat,public_lng,place_name,urgency,status,created_at from public.help_requests where status='open' and exists(select 1 from public.profiles where id=auth.uid() and not blocked and (role in ('user','family','volunteer','admin') or is_volunteer));
revoke all on public.help_requests_public from anon;grant select on public.help_requests_public to authenticated;
create or replace function public.accept_help(request_id uuid) returns void language plpgsql security definer set search_path=public as $$
declare r help_requests;v volunteer_profiles;
begin
 if not public.is_member() then raise exception 'Member access required';end if;
 select * into r from help_requests where id=request_id for update;
 select * into v from volunteer_profiles where user_id=auth.uid() and available;
 if r.id is null or r.status<>'open' or v.user_id is null or not(r.category=any(v.skills)) or r.requester_id=auth.uid() or r.requested_for_user_id=auth.uid() then raise exception 'Request unavailable or profile incomplete';end if;
 if v.lat is null or distance_m(v.lat,v.lng,r.public_lat,r.public_lng)>v.radius_km*1000 then raise exception 'Outside service radius';end if;
 if r.category in ('hospital_escort','transport','companionship') and not v.verified then raise exception 'Admin verification required';end if;
 if exists(select 1 from profiles where id=auth.uid() and blocked) then raise exception 'Blocked';end if;
 update help_requests set status='accepted',volunteer_id=auth.uid(),accepted_at=now() where id=r.id;
 if r.notify_family then insert into alerts(user_id,type,message,data) values(coalesce(r.requested_for_user_id,r.requester_id),'help_accepted',r.title,jsonb_build_object('request_id',r.id));end if;
end $$;
create or replace function public.transition_help(request_id uuid,next_status text,hours numeric default 0) returns void language plpgsql security definer set search_path=public as $$
declare r help_requests;
begin
 if not public.is_member() then raise exception 'Member access required';end if;
 select * into r from help_requests where id=request_id for update;
 if next_status='cancelled' and ((public.is_admin() and r.status in ('open','accepted','in_progress')) or ((r.requester_id=auth.uid() or public.can_full(r.requested_for_user_id)) and r.status in ('open','accepted'))) then update help_requests set status='cancelled' where id=r.id;return;end if;
 if auth.uid() is distinct from r.volunteer_id then raise exception 'Not assigned';end if;
 if next_status='in_progress' and r.status='accepted' then update help_requests set status=next_status where id=r.id;
 elsif next_status='completed' and r.status='in_progress' and hours between .1 and 24 then update help_requests set status=next_status,completed_at=now(),hours_spent=hours where id=r.id;
 else raise exception 'Invalid transition';end if;
end $$;
create or replace function public.help_contact(request_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare r help_requests;target uuid;begin
 if not public.is_member() then raise exception 'Member access required';end if;
 select * into r from help_requests where id=request_id and status in ('accepted','in_progress','completed');
 if r.volunteer_id=auth.uid() then target:=coalesce(r.requested_for_user_id,r.requester_id);
 elsif r.requester_id=auth.uid() or public.can_view(r.requested_for_user_id) then target:=r.volunteer_id;
 else raise exception 'Not allowed';end if;
 return (select jsonb_build_object('name',p.name,'phone',p.phone,'avatar_url',p.avatar_url,'verified',coalesce(v.verified,false)) from profiles p left join volunteer_profiles v on v.user_id=p.id where p.id=target);
end $$;
create or replace function public.volunteer_impact() returns jsonb language sql stable security definer set search_path=public as $$select jsonb_build_object('count',count(*),'hours',coalesce(sum(hours_spent),0),'rating',(select avg(f.rating) from help_feedback f join help_requests h on h.id=f.request_id where h.volunteer_id=auth.uid())) from help_requests where volunteer_id=auth.uid() and status='completed'$$;
revoke all on function public.accept_help(uuid),public.transition_help(uuid,text,numeric),public.help_contact(uuid),public.volunteer_impact() from public;
grant execute on function public.accept_help(uuid),public.transition_help(uuid,text,numeric),public.help_contact(uuid),public.volunteer_impact() to authenticated;
create or replace function public.log_help_family() returns trigger language plpgsql security definer set search_path=public as $$begin
 if new.requested_for_user_id is not null and auth.uid() is distinct from new.requested_for_user_id then insert into activity_log(user_id,changed_by,action,details) values(new.requested_for_user_id,auth.uid(),lower(tg_op)||':help',jsonb_build_object('request_id',new.id));end if;return new;end $$;
drop trigger if exists help_family_log on public.help_requests;
create trigger help_family_log after insert or update on public.help_requests for each row execute function public.log_help_family();
insert into public.modules(key,label_ml,label_en,icon,color,default_order) values('volunteer_help','സഹായം ചോദിക്കാം','Free volunteer help','🙋','#a85bb5',10) on conflict(key) do nothing;

create table if not exists public.posts(id uuid primary key default gen_random_uuid(),author_id uuid not null default auth.uid() references public.profiles,type text not null check(type in ('story','opinion','need','tip','achievement')),title text not null,text text,audio_url text,image_urls text[] not null default '{}',image_alt text,video_url text,transcript text,language text not null default 'ml',is_anonymous boolean not null default false,accessibility_tags text[] not null default '{}',status text not null default 'pending' check(status in ('pending','published','hidden')),category text not null default 'other',created_at timestamptz not null default now());
create table if not exists public.post_reactions(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.posts on delete cascade,user_id uuid not null default auth.uid() references public.profiles,reaction text not null check(reaction in ('❤️','🙏','💪','👏')),created_at timestamptz not null default now(),unique(post_id,user_id));
create table if not exists public.post_comments(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.posts on delete cascade,user_id uuid not null default auth.uid() references public.profiles,text text,audio_url text,status text not null default 'pending' check(status in ('pending','published','hidden')),created_at timestamptz not null default now());
create or replace function public.is_member() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where id=auth.uid() and role<>'gov_admin' and not blocked)$$;
create or replace function public.post_visible(target uuid) returns boolean language sql stable security definer set search_path=public as $$select public.is_member() and exists(select 1 from posts where id=target and (status='published' or author_id=auth.uid() or public.is_admin()))$$;
alter table public.posts enable row level security;
drop policy if exists posts_private on public.posts;
create policy posts_private on public.posts for select to authenticated using(public.is_member() and (author_id=auth.uid() or public.is_admin()));
drop policy if exists posts_create on public.posts;
create policy posts_create on public.posts for insert to authenticated with check(public.is_member() and author_id=auth.uid() and status='pending');
drop policy if exists posts_moderate on public.posts;
create policy posts_moderate on public.posts for update to authenticated using(public.is_admin()) with check(public.is_admin());
create or replace view public.posts_feed as select p.id,p.type,p.title,p.text,p.audio_url,p.image_urls,p.image_alt,p.video_url,p.transcript,p.language,p.is_anonymous,p.accessibility_tags,p.status,p.category,p.created_at,case when p.is_anonymous then null else a.name end as author_name from public.posts p join public.profiles a on a.id=p.author_id where p.status='published' and not a.blocked and public.is_member();
revoke all on public.posts_feed from anon;grant select on public.posts_feed to authenticated;
alter table public.post_reactions enable row level security;
drop policy if exists reactions_read on public.post_reactions;
create policy reactions_read on public.post_reactions for select to authenticated using(public.post_visible(post_id));
drop policy if exists reactions_write on public.post_reactions;
create policy reactions_write on public.post_reactions for all to authenticated using(user_id=auth.uid() and public.post_visible(post_id)) with check(user_id=auth.uid() and public.post_visible(post_id));
alter table public.post_comments enable row level security;
drop policy if exists comments_read on public.post_comments;
create policy comments_read on public.post_comments for select to authenticated using(public.post_visible(post_id) and (status='published' or user_id=auth.uid() or public.is_admin()));
drop policy if exists comments_create on public.post_comments;
create policy comments_create on public.post_comments for insert to authenticated with check(public.post_visible(post_id) and user_id=auth.uid() and status='pending');
drop policy if exists comments_moderate on public.post_comments;
create policy comments_moderate on public.post_comments for update to authenticated using(public.is_admin()) with check(public.is_admin());
create or replace function public.can_read_voice(path text) returns boolean language sql stable security definer set search_path=public as $$select public.is_member() and ((storage.foldername(path))[1]=auth.uid()::text or exists(select 1 from gallery_people g where g.voice_url=path and public.can_view(g.user_id)) or exists(select 1 from posts p where p.audio_url=path and public.post_visible(p.id)) or exists(select 1 from post_comments c where c.audio_url=path and public.post_visible(c.post_id) and (c.status='published' or c.user_id=auth.uid() or public.is_admin())) or exists(select 1 from help_requests r where r.voice_url=path and (r.requester_id=auth.uid() or r.volunteer_id=auth.uid() or public.can_view(r.requested_for_user_id))) or exists(select 1 from help_feedback f join help_requests r on r.id=f.request_id where f.voice_url=path and (r.requester_id=auth.uid() or r.volunteer_id=auth.uid())))$$;
drop policy if exists voices_read on storage.objects;
create policy voices_read on storage.objects for select to authenticated using(bucket_id='voices' and (owner=auth.uid() or public.can_read_voice(name)));
insert into public.modules(key,label_ml,label_en,icon,color,default_order) values('stories','നമ്മുടെ കഥകൾ','Our stories','📖','#b77ac0',11) on conflict(key) do nothing;

create table if not exists public.needs_surveys(id uuid primary key default gen_random_uuid(),subject_user_id uuid references public.profiles,filled_by uuid not null default auth.uid() references public.profiles,consent_given boolean not null check(consent_given=true),age_group text check(age_group in ('<18','18-40','41-60','61-75','75+')),gender text,district text,panchayat_or_municipality text,ward text,disability_types text[] not null default '{}',lives_alone boolean,has_caregiver boolean,needs text[] not null default '{}',has_disability_certificate boolean,receives_pension boolean,internet_access text check(internet_access in ('none','basic','good')),main_difficulty text,is_demo boolean not null default false,demo_key text unique,created_at timestamptz not null default now());
alter table public.needs_surveys enable row level security;
drop policy if exists survey_private on public.needs_surveys;
create policy survey_private on public.needs_surveys for select to authenticated using(public.is_member() and (filled_by=auth.uid() or subject_user_id=auth.uid() or public.can_full(subject_user_id)));
drop policy if exists survey_create on public.needs_surveys;
create policy survey_create on public.needs_surveys for insert to authenticated with check(public.is_member() and filled_by=auth.uid() and consent_given and not is_demo and (subject_user_id is null or public.can_full(subject_user_id)));
create or replace function public.survey_family_log() returns trigger language plpgsql security definer set search_path=public as $$begin
 if new.subject_user_id is not null and auth.uid() is not null and new.subject_user_id<>auth.uid() then insert into activity_log(user_id,changed_by,action,details) values(new.subject_user_id,auth.uid(),'insert:needs_survey',jsonb_build_object('consent_given',true));end if;return new;end $$;
drop trigger if exists survey_log on public.needs_surveys;
create trigger survey_log after insert on public.needs_surveys for each row execute function public.survey_family_log();
create or replace function public.suppressed_count(n bigint) returns text language sql immutable as $$select case when n<5 then '<5' else n::text end$$;
create or replace function public.gov_summary(filters jsonb default '{}') returns jsonb language plpgsql stable security definer set search_path=public as $$
declare result jsonb;begin
 if not exists(select 1 from profiles where id=auth.uid() and role in ('gov_admin','admin') and not blocked) then raise exception 'Government access required';end if;
 with scoped as (select * from needs_surveys s where consent_given
 and (coalesce(filters->>'district','')='' or s.district=filters->>'district')
 and (coalesce(filters->>'panchayat','')='' or s.panchayat_or_municipality=filters->>'panchayat')
 and (coalesce(filters->>'ward','')='' or s.ward=filters->>'ward')
 and (coalesce(filters->>'age','')='' or s.age_group=filters->>'age')
 and (coalesce(filters->>'disability','')='' or filters->>'disability'=any(s.disability_types))
 and (coalesce(filters->>'need','')='' or filters->>'need'=any(s.needs))),
 groups as (
 select 'need' as kind,unnest(needs) as label,count(*) as n from scoped group by 2
 union all select 'disability',unnest(disability_types),count(*) from scoped group by 2
 union all select 'age',age_group,count(*) from scoped group by 2
 union all select 'ward',coalesce(district,'')||' / '||coalesce(panchayat_or_municipality,'')||' / '||coalesce(ward,'')||' / '||unnest(needs),count(*) from scoped group by 2
 union all select 'area',coalesce(district,'')||' / '||coalesce(panchayat_or_municipality,'')||' / '||coalesce(ward,''),count(*) from scoped group by 2),
 kpis as(select count(*) as total,count(*) filter(where lives_alone) as alone,count(*) filter(where has_caregiver=false) as no_care,count(*) filter(where has_disability_certificate=false) as no_cert,count(*) filter(where receives_pension=false) as no_pension from scoped)
 select jsonb_build_object('total',suppressed_count(total),'demo',exists(select 1 from scoped where is_demo),
 'living_alone_pct',case when alone>=5 and total-alone>=5 then round(100.0*alone/total,1) else null end,
 'without_caregiver_pct',case when no_care>=5 and total-no_care>=5 then round(100.0*no_care/total,1) else null end,
 'without_certificate_pct',case when no_cert>=5 and total-no_cert>=5 then round(100.0*no_cert/total,1) else null end,
 'without_pension_pct',case when no_pension>=5 and total-no_pension>=5 then round(100.0*no_pension/total,1) else null end,
 'groups',coalesce((select jsonb_agg(jsonb_build_object('kind',kind,'label',label,'count',suppressed_count(n))) from groups),'[]'::jsonb),
 'signals',jsonb_build_object('wheelchair',suppressed_count((select count(*) from wheelchair_requests where status='pending')),'help',coalesce((select jsonb_agg(jsonb_build_object('category',category,'count',suppressed_count(n))) from (select category,count(*) n from help_requests where status='open' group by category)h),'[]'::jsonb),'needs_posts',coalesce((select jsonb_agg(jsonb_build_object('category',category,'count',suppressed_count(n))) from (select category,count(*) n from posts where type='need' and status='published' group by category)p),'[]'::jsonb))) into result from kpis;
 return result;
end $$;
revoke all on function public.gov_summary(jsonb) from public;grant execute on function public.gov_summary(jsonb) to authenticated;
