-- Keep an authoritative total; clients cannot manufacture service hours.
create or replace function public.guard_volunteer() returns trigger language plpgsql security definer set search_path=public as $$begin
 if auth.uid() is not null and not public.is_admin() then
 if tg_op='INSERT' then new.verified:=false;
 elsif new.verified is distinct from old.verified then raise exception 'Admin verification required';end if;end if;
 select coalesce(sum(hours_spent),0) into new.total_hours from help_requests where volunteer_id=new.user_id and status='completed';return new;end $$;
create or replace function public.update_volunteer_hours() returns trigger language plpgsql security definer set search_path=public as $$begin
 if new.status='completed' and old.status is distinct from 'completed' then update volunteer_profiles set total_hours=total_hours where user_id=new.volunteer_id;end if;return new;end $$;
drop trigger if exists help_hours on public.help_requests;
create trigger help_hours after update on public.help_requests for each row execute function public.update_volunteer_hours();
