 select id into g from auth.users where email=rec.email;
 insert into auth.identities(id,provider_id,user_id,identity_data,provider,last_sign_in_at,created_at,updated_at) values(gen_random_uuid(),g::text,g,jsonb_build_object('sub',g::text,'email',rec.email,'email_verified',true),'email',now(),now(),now());
