create or replace view public.wheelchairs_public as select w.id,w.owner_id,p.name as owner_name,p.verified as owner_verified,w.photo_urls,w.type,w.condition,w.offer,w.rent_per_day,w.duration,w.public_lat,w.public_lng,w.place_name,w.delivery,w.status,w.is_demo,w.created_at from public.wheelchairs w join public.profiles p on p.id=w.owner_id where w.approved and not p.blocked and public.is_member();
create or replace function public.can_view(target uuid) returns boolean language sql stable as $$select public.is_member() and (target=auth.uid() or public.family_level(target) is not null)$$;
create or replace function public.can_assist(target uuid) returns boolean language sql stable as $$select public.is_member() and (target=auth.uid() or public.family_level(target) in ('assist','full'))$$;
create or replace function public.can_full(target uuid) returns boolean language sql stable as $$select public.is_member() and (target=auth.uid() or public.family_level(target)='full')$$;
drop policy if exists profile_member_scope on public.profiles;
create policy profile_member_scope on public.profiles as restrictive for select to authenticated using(id=auth.uid() or public.is_member());
do $$declare t text;begin foreach t in array array['user_settings','family_links','activity_log','medicines','med_logs','tasks','memory_notes','contacts','emergency_info','checkins','checkin_rules','sos_events','sign_cards','quick_phrases','helplines','wheelchairs','wheelchair_requests','reports','messages'] loop
 execute format('drop policy if exists phase2_member_scope on public.%I',t);
 execute format('create policy phase2_member_scope on public.%I as restrictive for all to authenticated using(public.is_member()) with check(public.is_member())',t);
end loop;end $$;
create or replace function public.get_request_contact(req uuid)
returns table (phone text, whatsapp boolean, lat double precision, lng double precision, name text)
language plpgsql security definer set search_path = public as $$
declare r wheelchair_requests; w wheelchairs;
begin
  if not public.is_member() then return;end if;
  select * into r from wheelchair_requests where id = req;
  if r.id is null or r.status not in ('accepted','returned') then return; end if;
  select * into w from wheelchairs where id = r.wheelchair_id;
  if public.can_view(r.seeker_id) then
    return query select p.phone, p.whatsapp, w.lat, w.lng, p.name from profiles p where p.id = w.owner_id;
  elsif auth.uid() = w.owner_id then
    return query select p.phone, p.whatsapp, null::double precision, null::double precision, p.name from profiles p where p.id = r.seeker_id;
  end if;
end $$;
create or replace function public.create_link_code() returns text
language plpgsql security definer set search_path = public as $$
declare c text;
begin
  if not public.is_member() then raise exception 'Member access required';end if;
  if auth.uid() is null then raise exception 'not signed in'; end if;
  delete from family_links where user_id = auth.uid() and family_id is null;
  loop
    c := lpad((floor(random() * 1000000))::int::text, 6, '0');
    exit when not exists (select 1 from family_links where link_code = c and family_id is null);
  end loop;
  insert into family_links (user_id, link_code, status) values (auth.uid(), c, 'pending');
  return c;
end $$;
create or replace function public.claim_link_code(code text) returns uuid
language plpgsql security definer set search_path = public as $$
declare l family_links;
begin
  if not public.is_member() then raise exception 'Member access required';end if;
  if auth.uid() is null then raise exception 'not signed in'; end if;
  select * into l from family_links
   where link_code = code and family_id is null and status = 'pending'
     and created_at > now() - interval '15 minutes'
   order by created_at desc limit 1;
  if l.id is null then return null; end if;
  if l.user_id = auth.uid() then return null; end if;
  update family_links set status = 'revoked'
   where user_id = l.user_id and family_id = auth.uid() and status in ('pending','active');
  update family_links set family_id = auth.uid() where id = l.id;
  return l.id;
end $$;
commit;
